-- Failed QA runs become governed remediation requests; passing reruns become permanent regressions.
create table if not exists public.autonomous_qa_remediations(id uuid primary key default gen_random_uuid(),scenario_id uuid not null references public.autonomous_qa_scenarios(id),failed_run_id uuid not null references public.autonomous_qa_runs(id),status text not null default 'OPEN' check(status in('OPEN','FIXED','VERIFIED')),owner_department integer not null,diagnosis text not null,requested_fix text not null,rerun_id uuid references public.autonomous_qa_runs(id),created_at timestamptz not null default now(),verified_at timestamptz);
alter table public.autonomous_qa_remediations enable row level security;do $$begin create policy qa_remediation_superadmin_read on public.autonomous_qa_remediations for select to authenticated using(private.is_superadmin());exception when duplicate_object then null;end$$;grant select on public.autonomous_qa_remediations to authenticated;
create or replace function public.superadmin_register_qa_remediation(p_failed_run_id uuid,p_owner_department integer,p_requested_fix text)
returns public.autonomous_qa_remediations language plpgsql security definer set search_path=public,private,auth as $$declare rr public.autonomous_qa_runs%rowtype;r public.autonomous_qa_remediations%rowtype;begin if auth.uid() is null or not private.is_superadmin()then raise exception 'SUPERADMIN_REQUIRED' using errcode='42501';end if;select * into rr from public.autonomous_qa_runs where id=p_failed_run_id and status='FAILED';if rr.id is null then raise exception 'FAILED_QA_RUN_REQUIRED';end if;insert into public.autonomous_qa_remediations(scenario_id,failed_run_id,owner_department,diagnosis,requested_fix)values(rr.scenario_id,rr.id,p_owner_department,coalesce(rr.diagnosis,'No diagnosis persisted'),btrim(p_requested_fix))returning * into r;return r;end$$;
revoke all on function public.superadmin_register_qa_remediation(uuid,integer,text) from public;grant execute on function public.superadmin_register_qa_remediation(uuid,integer,text) to authenticated;